{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C01"],
      "claim": "Ampicillin absolute oral bioavailability was 48.1 ± 19.3% in nonpregnant women relative to intravenous administration, clearly above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C55"],
      "claim": "Rivastigmine absolute oral bioavailability was 71.7% (range 21.6–118.5%) after a 6 mg capsule compared with a 2 mg intravenous dose, supporting high bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "PEMA absolute oral bioavailability was 91 ± 4.4% in normal volunteers compared with intravenous dosing, strongly supporting high bioavailability.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All retrieved evidence molecules show human oral bioavailability values above 20%, with most values between 35% and 95%; the lowest reported value is approximately 25%, still above the threshold. Therefore, high bioavailability at the F >= 20% cutoff is supported.",
  "evidence_gaps": [
    "Some records are qualitative or report ranges rather than exact absolute bioavailability values, but all numeric values remain above 20%.",
    "Rivastigmine shows dose-dependent bioavailability (about 36% at 3 mg vs 60–72% at 6 mg), but both levels are above the threshold."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

